// ============================================================
// logoData.js
// The ISP logo, embedded directly as base64 so it always renders
// no matter how the static /public folder is served or cached on
// a given deployment - no separate image file to go missing or
// 404. LOGO_DATA_URI is the higher-resolution version used inline
// in the app (sidebar, login screen); LOGO_FAVICON_DATA_URI is a
// smaller 32x32 version sized for the browser tab icon.
// ============================================================

export const LOGO_DATA_URI = 'data:image/png;base64,';

export const LOGO_FAVICON_DATA_URI = 'data:image/png;base64,';
